    "變成小精靈時，看你最常做什麼：釣魚 💧、添柴煮菜 🔥、採集 🍃、休息聊天 ☁️、看星星許願 ⭐、迷霧森林採蘑菇 🍄（晚上或營火時間玩，星星會多算一點）": "When it becomes a spirit, it matches what you do most: fishing 💧, adding wood & cooking 🔥, gathering 🍃, resting & chatting ☁️, stargazing & wishes ⭐, Misty Forest mushrooms 🍄 (playing at night or during campfire time counts a little extra for Star)",
    "變成小精靈時，看你最常做什麼：釣魚 💧、添柴煮菜 🔥、採集 🍃、休息聊天 ☁️、看星星許願 ⭐、迷霧森林採蘑菇 🍄。長大後也可以花 300 🌰 換。": "When it becomes a spirit, it matches what you do most: fishing 💧, adding wood & cooking 🔥, gathering 🍃, resting & chatting ☁️, stargazing & wishes ⭐, Misty Forest mushrooms 🍄. Once grown you can also switch for 300 🌰.",
    "想多養一隻：孵蛋器 300 🌰，10 分鐘孵好；一次帶 1 隻出門，最多養 12 隻": "Want another? Incubator 300 🌰, hatches in 10 minutes. Bring 1 along at a time, keep up to 12",
    "小精靈會跟在你身邊，玩遊戲就會長大。": "Your spirit follows you and grows as you play.",
    "小精靈、孵蛋器、配件只能用松果買，不用花錢": "Spirits, incubators and accessories are pinecones only, no real money",
    "在小舖「✨ 小精靈」買蛋：第一顆 100 🌰，馬上孵出來": "Buy an egg in the shop's \"✨ Spirit\" tab: the first one is 100 🌰 and hatches right away",
    "可以取名字、摸摸它、先收起來；沒來玩也不會生病或離開": "You can name it, pet it or put it away. It won't get sick or leave if you're away",
    "到小舖「✨ 小精靈」買小精靈蛋（第一顆 100 🌰，馬上孵出來）。它會跟在你身邊，玩遊戲、餵料理就會長大。": "Buy a spirit egg in the shop's \"✨ Spirit\" tab (first one 100 🌰, hatches right away). It follows you and grows as you play and feed it.",
    "✨ 小精靈會變成哪一種？": "✨ What kind will my spirit become?",
    "✨ 小精靈怎麼養？": "✨ How do I raise a spirit?",
    "3 個階段：小光點 → 小精靈（親密度 60）→ 長大（親密度 400，有翅膀和光環）": "3 stages: Little Light → Spirit (bond 60) → Grown (bond 400, with wings and a halo)",
    "花 300 🌰 換成 6 種裡的任何一種": "Spend 300 🌰 to switch to any of the 6 kinds",
    "釣魚 💧、顧火煮菜 🔥、採集 🍃、休息聊天 ☁️、看星星許願 ⭐、迷霧森林採蘑菇 🍄": "Fishing 💧, fire & cooking 🔥, gathering 🍃, resting & chatting ☁️, stargazing & wishes ⭐, Misty Forest mushrooms 🍄",
    "孵出來是一顆小光點，飄在你肩膀旁邊。玩遊戲、餵料理，它就會慢慢長大，看你怎麼玩變成 💧 水滴、🔥 火苗、🍃 葉子、☁️ 雲朵、⭐ 星星或 🍄 蘑菇。": "It hatches as a little light that floats by your shoulder. Play and feed it to help it grow; how you play decides if it becomes 💧 Droplet, 🔥 Flame, 🍃 Leaf, ☁️ Cloud, ⭐ Star or 🍄 Mushroom.",
    "怎麼長大：釣魚、添柴、煮菜、採集、休息、聊天、看星星、許願、種菜收成，都會加親密度；餵料理長最快": "How it grows: fishing, adding wood, cooking, gathering, resting, chatting, stargazing, wishing and harvesting all add bond points. Feeding dishes is fastest",
    "🌟 長大以後可以花 {n} 🌰 換成任何樣子": "🌟 Once grown, spend {n} 🌰 to change to any look",
    "變成小精靈時，看你最常做什麼：釣魚 💧、顧火・煮菜 🔥、採集 🍃、休息・陪人聊天 ☁️、看星星・許願・晚上玩 ⭐、迷霧森林・採蘑菇・種菜收成 🍄": "When it becomes a spirit, it matches what you do most: fishing 💧, fire & cooking 🔥, gathering 🍃, resting & chatting ☁️, stargazing, wishes & playing at night ⭐, Misty Forest, mushrooms & harvesting 🍄",
    "🥚 小精靈蛋（附孵蛋器）": "🥚 Spirit egg (with incubator)",
    "🥚 去小舖買小精靈蛋": "🥚 Buy a spirit egg at the shop",
    "買小精靈蛋 🌰 {p}": "Buy spirit egg 🌰 {p}",
    "買了馬上孵出一顆小光點，飄在你肩膀旁邊；玩遊戲、餵料理就會慢慢長大。": "A little light hatches right away and floats by your shoulder. Play and feed it to help it grow.",
    "花 {n} 🌰 買小精靈蛋（附孵蛋器）？買了馬上孵出來": "Spend {n} 🌰 on a spirit egg (with incubator)? It hatches right away",
    "第一顆 {a} 🌰，之後想多養一隻，每顆 {b} 🌰（10 分鐘孵好）。": "First egg {a} 🌰. After that, each extra one is {b} 🌰 (hatches in 10 minutes).",
    "現在養了 {n}／{m} 隻。": "You have {n}/{m}.",
    "想多養幾隻": "Want more?",
    "小舖「✨ 小精靈」買小精靈蛋（第一顆 100 🌰），玩遊戲會長大，可以餵它、取名字": "Buy a spirit egg in the shop's \"✨ Spirit\" tab (first one 100 🌰). It grows as you play; feed it and name it",
    "孵出來是一顆小光點，飄在你肩膀旁邊。釣魚、添柴、煮菜、採集、餵料理，它就會慢慢長大，看你怎麼玩變成 💧 水滴、🔥 火苗或 🍃 葉子。": "It hatches as a little light that floats by your shoulder. Fishing, adding wood, cooking, gathering and feeding help it grow, and how you play decides if it becomes 💧 Droplet, 🔥 Flame or 🍃 Leaf.",
    "可以養小精靈了": "You can raise a spirit now",
    "可以取名字、摸摸它；不養也沒關係，想養再買就好。": "You can name it and pet it. It's fine not to have one; buy one whenever you like.",
    "到小舖「✨ 小精靈」買小精靈蛋（第一顆 100 🌰，馬上孵出來），小光點會飄在你肩膀旁邊，別人也看得到": "Buy a spirit egg in the shop's \"✨ Spirit\" tab (first one 100 🌰, hatches right away). A little light floats by your shoulder, and others can see it",
    "到「🏪 營地小舖 → ✨ 小精靈」買一顆小精靈蛋（附孵蛋器），第一顆 {n} 🌰，買了馬上孵出來！": "Buy a spirit egg (with incubator) at \"🏪 Camp Shop → ✨ Spirit\". The first one is {n} 🌰 and hatches right away!",
    "再買孵蛋器（300 🌰，10 分鐘孵好）；可以取名字、收起來換一隻帶，一次帶 1 隻": "Buy another incubator (300 🌰, hatches in 10 minutes). Name them and switch which one comes along; one at a time",
    "你還沒有小精靈": "You don't have a spirit yet",
    "✨ 孵出來了！一顆小光點跟著你了，點上方「✨ 小精靈」看看它": "✨ It hatched! A little light is following you. Tap \"✨ Spirit\" at the top to see it",
    "按上方「📢 更新」，可以往前翻以前的更新": "Tap \"📢 Updates\" at the top and page back through earlier updates",
    "以前的更新也看得到": "See earlier updates too",
    "帳篷營地每區入口都有一台，大家都能騎，按 E 騎、再按 E 下車": "There's one at every Tent Camp area entrance. Anyone can ride: press E to ride, E again to get off",
    "公用腳踏車": "Public bikes",
