    "<kbd>E</kbd> 🚲 騎公用腳踏車（再按 E 下車）": "<kbd>E</kbd> 🚲 Ride the public bike (press E again to get off)",
    "🚲 公用腳踏車・大家都能騎": "🚲 Public bike · Anyone can ride",
