    "🌟 長大以後可以花 {n} 🌰 換成任何樣子（☁️ 雲朵、⭐ 星星、🍄 蘑菇只能這樣換到）": "🌟 Once grown, spend {n} 🌰 to change to any look (☁️ Cloud, ⭐ Star and 🍄 Mushroom are only available this way)",
