    "養好幾隻可以收起來，挑一隻帶在身邊；每一隻都可以取名字。": "Keep several, put some away and pick one to bring along. Each can have a name.",
    "長大後可以換樣子": "Change its look once grown",
    "釣魚、添柴、煮菜、採集、餵料理都會長大：小光點 → 小精靈 → 長大（翅膀＋光環）": "Fishing, adding wood, cooking, gathering and feeding all help: Little Light → Spirit → Grown (wings + halo)",
