    "買孵蛋器 🌰 {p}": "Buy incubator 🌰 {p}",
    "變成小精靈時，看你最常做什麼：釣魚 💧、顧火・煮菜 🔥、採集 🍃": "When it becomes a spirit, it matches what you do most: fishing 💧, fire & cooking 🔥, gathering 🍃",
    "親密度": "Bond",
    "花 {n} 🌰 買一個孵蛋器？10 分鐘後孵出一顆新的小光點": "Spend {n} 🌰 on an incubator? A new little light hatches in 10 minutes",
    "花 {n} 🌰 把小精靈換成{icon} {name}？": "Spend {n} 🌰 to change your spirit to {icon} {name}?",
    "花 300 🌰 換成任何一種，☁️ 雲朵、⭐ 星星、🍄 蘑菇只能這樣換到": "Spend 300 🌰 to switch to any kind. ☁️ Cloud, ⭐ Star and 🍄 Mushroom are only available this way",
    "看它、摸摸它、餵它吃料理（喜歡的料理長更快）": "See it, pet it, feed it dishes (favorites help it grow faster)",
    "看你怎麼玩決定樣子": "Its look depends on how you play",
    "現在養了 {n}／{m} 隻。第一隻小精靈免費，大家一進來就有。": "You have {n}/{m}. Everyone gets their first spirit free.",
    "現在最像：": "Most like right now: ",
    "玩遊戲會長大": "Grows as you play",
    "沒餵成功，再試一次": "Couldn't feed. Try again",
    "沒買成功，再試一次": "Couldn't buy. Try again",
    "沒換成功，再試一次": "Couldn't switch. Try again",
    "沒來玩也不會生病、不會離開，它會一直等你 💛": "It won't get sick or leave if you're away. It'll always wait for you 💛",
    "沒來也沒關係，好幾天沒來它還會衝過來找你": "It's okay to be away. After a few days it'll rush over to greet you",
    "每個人都有小精靈": "Everyone has a spirit",
    "每個人身邊都有一顆小光點，玩遊戲會長大；上方「✨ 小精靈」可以餵它、取名字、孵新的": "Everyone has a little light that grows as you play. Use \"✨ Spirit\" at the top to feed it, name it, or hatch a new one",
    "松果不夠，需要 {n} 🌰": "Not enough pinecones. You need {n} 🌰",
    "最常釣魚變 💧 水滴、顧火煮菜變 🔥 火苗、採集變 🍃 葉子": "Fish most → 💧 Droplet, tend fire & cook → 🔥 Flame, gather → 🍃 Leaf",
    "放一顆小精靈蛋，10 分鐘後孵出一顆新的小光點，再靠玩遊戲把它養大。": "Place a spirit egg. In 10 minutes a new little light hatches; raise it by playing.",
    "想多養一隻？到「🏪 營地小舖 → ✨ 小精靈」買 🥚 孵蛋器（{n} 🌰）": "Want another? Buy a 🥚 incubator at \"🏪 Camp Shop → ✨ Spirit\" ({n} 🌰)",
    "怎麼長大：🎣 釣到魚、🔥 添柴、🍲 煮菜、🍄 採集，都會加親密度；餵料理長最快": "How it grows: 🎣 catching fish, 🔥 adding wood, 🍲 cooking and 🍄 gathering all add bond points. Feeding dishes is fastest",
