    "👉 看月票": "👉 See the pass",
    "上方「💝 支持營地」可以買。每天多拿松果、可以買月票家具；不會自動續扣，不買也能玩。": "Buy it from “💝 Support” at the top. Get extra pinecones daily and buy pass furniture; it never auto-renews, and you can play fine without it.",
