    "🎁 即將推出，敬請期待！": "🎁 Coming soon—stay tuned!",
    "先點選喜歡的那一款。同一個月再贊助一次，送你另一款。": "Pick the one you like first. Sponsor again in the same month to get the other one.",
    "這座營地是一個人慢慢做出來的，伺服器需要一點費用。贊助 NT${n} 以上，送你 {m} 月限定假髮（2 選 1）。": "This camp is made slowly by one person, and the server costs a little. Sponsor NT${n} or more and get a limited wig for month {m} (pick 1 of 2).",
