    "女生款": "Girls' style",
    "男生款": "Boys' style",
    "一次付清，不會自動續扣。天數接在剩下的天數後面。可用台灣的信用卡、Apple Pay、綠界Pay、ATM、超商條碼。": "One-time payment, no auto-renewal. Days are added after your remaining days. Taiwan credit cards, Apple Pay, ECPay Pay, ATM and convenience-store barcodes accepted.",
    "免費玩家：釣魚每天前 {f} 條照價算、掛機每天最多 {s} 顆。月票只會加快松果累積，遊戲裡的東西不買也拿得到；到期後買過的東西都保留。": "Free players: the first {f} fish a day earn full pinecones, idle pinecones cap at {s} a day. A pass only speeds up pinecones—everything in the game can be earned without buying; you keep what you bought after it ends.",
    "🌌 星空門牌、每月搬家免費 2 次": "🌌 Starry nameplate, 2 free moves a month",
    "🎫 可以買月票家具、跳色": "🎫 Can buy pass furniture & two-tone colors",
