    "請先勾選年齡確認": "Please tick the age confirmation first",
    "‹ 返回": "‹ Back",
    "未成年請先問爸爸媽媽。虛擬商品付款後立即送達，送達後不提供退款；重複扣款或沒有收到，請到「👫 好友 → ✉️ 聯絡作者」告訴我們。": "If you're under 18, please ask your parents first. Virtual items are delivered right after payment and can't be refunded once delivered; if you were charged twice or didn't receive it, tell us via “👫 Friends → ✉️ Contact the creator”.",
    "我已滿 18 歲；或未滿 18 歲，已經問過爸爸媽媽，他們同意我購買。": "I am 18 or older; or I am under 18 and my parents have said I may buy this.",
