    "🏢 同一個網路（家人、同事共用 Wi‑Fi）：要玩 {m} 分鐘、而且要真的玩一下（釣魚、採集、撿垃圾、做任務），每天最多算 {n} 位": "🏢 Same network (family or coworkers on one Wi‑Fi): they must stay {m} min and actually play (fish, gather, pick up trash, do tasks); up to {n} per day",
    "⏳ 朋友中途跳出去沒關係，30 分鐘內回來還是算": "⏳ It's fine if your friend leaves for a bit — it still counts if they come back within 30 min",
    "❌ 不算：自己點自己的連結、只傳圖片沒掃 QR、光按分享沒人點進來": "❌ Doesn't count: opening your own link, sending the image without scanning the QR, or sharing when nobody opens it",
    "🔁 每日造型一天只能拿一次；營火之約同一對朋友一天算一次": "🔁 One daily outfit per day; each pair of friends gets one campfire date per day",
