    "📌 獎勵都是系統照上面的規則自動發的：沒有符合條件就不會拿到，作者不另外補發。邀請前請先跟朋友確認好": "📌 Rewards are given automatically by the rules above: if the conditions aren't met there's no reward, and the creator can't re-send them. Check with your friend before inviting",
    "❌ 不算的情況：自己點自己的連結、只傳圖片沒掃 QR、朋友以前就來過（不算「新朋友」，但每日造型、營火之約還是算）": "❌ Doesn't count: clicking your own link, sending only the image without scanning the QR, or a friend who's visited before (not a “new friend”, but still counts for the daily outfit and Campfire Date)",
    "⏳ 朋友中途跳出去沒關係，30 分鐘內回來還是算；時間到之前關掉、30 分鐘內沒回來就不算": "⏳ It's fine if your friend steps away—it still counts if they're back within 30 min; closing early and not returning within 30 min doesn't count",
    "🏢 <b>同一個網路</b>（同事、家人用同一個 Wi‑Fi）：朋友要待 {m} 分鐘，而且要玩一下（釣魚、採集、撿垃圾、做任務都可以），同一個網路每天最多算 {n} 位": "🏢 <b>Same network</b> (coworkers or family on one Wi‑Fi): your friend needs to stay {m} min and actually play (fish, forage, pick up litter or do a quest); up to {n} friends per network per day",
    "🔥 <b>營火之約</b>：早上、晚上 9:30～10:00 營火時間，朋友點你的連結進來待滿 {m} 分鐘，兩個人都拿限定造型（依序：營火圍巾 → 烤棉花糖帽 → 流星燈背架），同一對朋友每天算一次": "🔥 <b>Campfire Date</b>: during campfire time (9:30–10:00 am/pm), a friend joins via your link and stays {m} min—you both get a limited outfit (in order: Ember Scarf → Marshmallow Hat → Meteor Lantern Pack); once per pair per day",
    "👒 <b>每日造型</b>：任何朋友（新朋友、老朋友都算）點你的連結進來玩 {m} 分鐘；或自己完成「今日挑戰」3 題": "👒 <b>Daily outfit</b>: any friend (new or returning) plays {m} min via your link—or finish the 3 “Today's challenges” yourself",
    "👫 <b>新朋友</b>：第一次來營地、點你的連結（或掃 QR 邀請圖）進來，待滿 {m} 分鐘 → 你拿 {g} 顆松果＋這週限定造型；累積 1、3、5 位送禮物家具": "👫 <b>New friends</b>: first visit, joined via your link (or QR invite) and stayed {m} min → you get {g} pinecones + this week's outfit; gift furniture at 1, 3 and 5 friends",
    "📜 怎樣才算？邀請前先看規則": "📜 What counts? Read the rules before inviting",
