    "螳螂": "Praying mantis",
    "舉著兩把小鐮刀": "Holds up two little sickles",
    "竹節蟲": "Stick insect",
    "仔細看才發現不是樹枝": "Look closely — it's not a twig",
    "彩虹吉丁蟲": "Rainbow jewel beetle",
    "背上閃著彩虹光，很難遇到": "Rainbow shimmer on its back — hard to find",
    "流星劍魚王": "Meteor Swordfish King",
    "只在每晚 9:30，追著流星衝進湖裡": "Only at 9:30 each night — dives into the lake chasing meteors",
    "螢光幽靈魚王": "Glowing Ghost Fish King",
    "只在每晚 9:30，在營火河畔若隱若現": "Only at 9:30 each night — flickers by the campfire pond",
    "🌙 每晚 7 點～11 點，每半小時一場小活動（9:30 營火時間有魚王）": "🌙 Mini events every 30 min, 7–11 PM nightly (fish kings at 9:30 campfire time)",
    "想動就去釣魚、疊石頭；想靜就在火邊坐著。每晚 7 點～11 點，每半小時一場小活動 🎣": "Feel active? Fish or stack stones. Feel quiet? Just sit by the fire. Mini events every 30 minutes from 7 to 11 PM 🎣",
    "🍄 迷霧森林：地上有發光圈圈的蘑菇、果實、野花，走過去按 E 採摘；空中飛的蟲蟲要用捕蟲網（{p} 🌰）按 E 捕。🐚 湖畔碼頭的岸邊可以撿石頭和貝殼。✨ 晚上 8～10 點營火附近偶爾會有寶藏。第一次找到新的種類送松果，全部收集完再送 {b} 顆 🌰": "🍄 Misty Woods: walk up to mushrooms, berries and flowers with a glowing ring and press E to pick; catch flying bugs with a bug net ({p} 🌰). 🐚 Pick up stones and shells on the lake shore. ✨ Treasures sometimes appear near the campfire 8–10 PM. New finds give pinecones; complete the guide for {b} more 🌰",
    "🦋 捕蟲網：已經有了": "🦋 Bug net: owned",
    "🦋 捕蟲網：還沒有": "🦋 Bug net: not yet",
    "買一支 🌰 {p}": "Buy one 🌰 {p}",
    "🥕 菜園收成": "🥕 Garden harvest",
    "🦋 買了一支捕蟲網！看到空中飛的蟲蟲，走近按 E 捕捉": "🦋 Got a bug net! Walk up to a flying bug and press E",
    "松果不夠，還差 {n} 顆 🌰": "Not enough pinecones — {n} more 🌰",
    "🦋 捕蟲網": "🦋 Bug net",
    "空中飛的蟲蟲要用捕蟲網才捕得到。買一支之後一直都能用：白天有瓢蟲、金龜子、螳螂⋯，晚上有螢火蟲、獨角仙、月光蛾⋯": "You need a bug net for flying bugs. Buy once, keep forever: ladybugs, scarabs and mantises by day; fireflies, rhino beetles and luna moths at night…",
    "🦋 買一支捕蟲網 🌰 {p}": "🦋 Buy a bug net 🌰 {p}",
    "第一個捐的人": "First donor",
    "🎁 捐出": "🎁 Donate",
    "還沒有人捐": "Not donated yet",
    "🏛️ 營地標本櫃 {n}／{total}": "🏛️ Camp Museum {n}/{total}",
    "大家一起把採集到的東西捐進標本櫃，每一格都會寫上「第一個捐的人」的名字。捐出一個送松果（★ 越多送越多）。": "Everyone fills the museum together — each slot shows the name of its first donor. Donating gives pinecones (more ★, more pinecones).",
    "🏛️ 捐進標本櫃了！你的名字會留在這一格 +{n} 🌰": "🏛️ Donated! Your name stays on this slot +{n} 🌰",
    "剛好有人先捐了：{name}": "Someone beat you to it: {name}",
    "連上伺服器才能看標本櫃": "Connect to the server to see the museum",
    "🏛️ {name} 把{icon} {item}捐進了標本櫃": "🏛️ {name} donated {icon} {item} to the museum",
    "🔨 手作": "🔨 Craft",
    "🔨 手作家具": "🔨 Handmade furniture",
    "做一個": "Make",
    "用採集籃裡的東西做家具，做好會放進帳篷背包，回帳篷按「🛠️ 布置」擺出來。「任意」的材料會先用數量多、常見的，★★★ 稀有的不會被拿去用。": "Make furniture from your basket. It goes to your tent inventory — place it with 🛠️ Decorate. \"Any\" materials use your most plentiful common items first; ★★★ rare ones are never used.",
    "🔨 做好了：{icon} {name}！放進帳篷背包了": "🔨 Made {icon} {name}! It's in your tent inventory",
    "材料不夠喔": "Not enough materials",
    "🍲 料理": "🍲 Cooking",
