    "任意{name}": "any {name}",
    "種子用松果買（越慢長的越貴），種下去等幾小時就能收成，放著不收也不會枯掉。朋友路過可以幫忙澆水，少等 30 分鐘、收成多一個。收成的蔬菜可以拿去營火旁煮料理，或當手作家具的材料。": "Buy seeds with pinecones (slower crops cost more). Harvest after a few hours — crops never wither. Friends can water to make them 30 min faster and +1 harvest. Cook veggies at the campfire or use them for crafting.",
    "🌱 種下{icon} {name}了！大約 {h} 小時後收成": "🌱 Planted {icon} {name}! Ready in about {h} h",
    "松果不夠喔": "Not enough pinecones",
    "沒種成，再試一次吧": "Couldn't plant — try again",
    "🔥 約朋友・分享送禮": "🔥 Invite friends · Gifts",
    "朋友要「點你的連結」或「掃邀請圖上的 QR Code」進來才算數": "Friends must open your link or scan the QR code on your invite image to count",
    "📋 複製連結": "📋 Copy link",
    "📤 分享連結": "📤 Share link",
    "🖼️ 邀請圖（有 QR Code）": "🖼️ Invite image (QR)",
    "👒 今天的每日造型・朋友點你的連結進來玩 1 分鐘，或完成下面的「今日挑戰」": "👒 Today's daily outfit · a friend plays 1 minute via your link, or finish “Today's challenges” below",
    "🌟 這週限定造型・朋友第一次透過你的連結來玩，待滿 {m} 分鐘": "🌟 Weekly outfit · a friend joins via your link for the first time and stays {m} min",
    "🔥 營火之約限定・晚上 9:30～10:00 朋友透過你的連結進來，兩個人都拿到": "🔥 Campfire date · a friend joins via your link 9:30–10:00 PM and you both get it",
    "{kind}・第一次分享": "{kind} · first share",
    "{kind}・{n} 位朋友透過你的連結來玩": "{kind} · {n} friends join via your link",
    "已經有 {n} 位朋友透過你的連結來玩。每位朋友第一次來、待滿 {m} 分鐘，你就多 {g} 顆松果。只傳圖片的話，請朋友掃圖上的 QR Code 才算喔": "{n} friends have joined via your link. Each new friend who stays {m} min gives you {g} pinecones. If you only send the image, ask friends to scan its QR code",
    "複製不了，請長按上面的連結自己複製": "Couldn't copy — press and hold the link above to copy it",
    "📋 已複製邀請連結，貼到 LINE、Threads、IG 給朋友吧": "📋 Invite link copied — paste it to friends on LINE, Threads or IG",
    "有些 App（像 IG、LINE）分享圖片時會把連結拿掉，朋友掃圖上的 QR Code 一樣算是透過你的連結進來 📱": "Some apps (like IG and LINE) drop the link when sharing an image — friends can scan the QR code on it instead 📱",
    "朋友點連結進來玩 1 分鐘，就送你今天的每日造型：{name}": "When a friend opens the link and plays for 1 minute, you get today's outfit: {name}",
    "📱 掃描 QR Code": "📱 Scan the QR code",
    "就會出現在我旁邊，免安裝打開就能玩": "to appear right next to me — no install needed",
    "就會出現在我旁邊": "to appear right next to me",
    "免安裝，打開就能玩": "No install — just open and play",
    "🖼️ QR 邀請圖": "🖼️ QR invite image",
    "📋 複製文案": "📋 Copy caption",
    "📋 文案和連結複製好了，貼到 LINE、Threads、IG 都可以": "📋 Caption and link copied — paste it into LINE, Threads or IG",
    "✅ 圖片分享出去了！文案和連結也幫你複製好了，如果朋友那邊沒看到連結，在聊天框長按「貼上」就好": "✅ Image shared! The caption and link are copied too — if your friend didn't get the link, just paste it in the chat",
    "✅ 分享出去了！圖片可以按「存圖」另外傳": "✅ Shared! Use Save image to send the picture too",
    "按「📤 分享」會順便複製下面的文案和連結：如果 App 只送出圖片，在聊天框貼上就好；朋友掃圖上的 QR Code 也算 📱": "📤 Share also copies the caption and link below — if the app only sends the image, just paste it in the chat. Scanning the QR code counts too 📱",
    "🌱 還可以再開墾（最多 {max} 格）": "🌱 You can clear more plots (up to {max})",
    "➕ 開墾第 {n} 格 🌰 {p}": "➕ Clear plot {n} 🌰 {p}",
    "🌱 開墾好了！菜園現在有 {n} 格": "🌱 Cleared! Your garden now has {n} plots",
    "現在不能開墾": "Can't clear a plot right now",
    "魚拓": "Fish prints",
    "🎣 捐魚拓": "🎣 Donate print",
    "大家一起把採集到的東西、釣過的魚拓捐進標本櫃，每一格都會寫上「第一個捐的人」。每個人每天只能捐一件，慢慢一起填滿吧！捐出一件送松果（★ 越多送越多）。": "Everyone fills the museum with finds and fish prints — each slot shows its first donor. Each person can donate one item per day, so we fill it slowly together! Donating gives pinecones (more ★, more pinecones).",
    "🎁 今天還可以捐 {n} 件": "🎁 You can donate {n} more today",
    "✅ 今天已經捐過了，明天再來捐下一件吧": "✅ You've donated today — come back tomorrow for the next one",
    "今天已經捐過了，明天再來捐下一件吧": "You've donated today — come back tomorrow",
    "垃圾圖鑑全部收集完就拿到": "Complete the trash guide to get it",
    "垃圾圖鑑收集完": "Complete the trash guide",
    "淨灘小隊": "Cleanup crew",
    "♻️ 垃圾圖鑑新收錄：{icon} {name}！+{n} 🌰（{c}／{t}）": "♻️ New in trash guide: {icon} {name}! +{n} 🌰 ({c}/{t})",
    "♻️ 撿起了{icon} {name}，記得拿去營火旁的回收桶": "♻️ Picked up {icon} {name} — take it to the recycling bin by the campfire",
    "🏆 垃圾圖鑑全部收集完成！送你「淨灘小隊領巾」": "🏆 Trash guide complete! Here's the Cleanup Crew bandana",
