    "連上伺服器才能回收": "Connect to the server to recycle",
    "垃圾袋是空的。湖邊、帳篷營地路邊、營火附近偶爾會有垃圾，撿起來再拿過來丟 ♻️（今天大家一起回收了 {n} 件）": "Your trash bag is empty. Trash sometimes appears by the lake, along camp paths and near the campfire — pick it up and bring it here ♻️ (everyone recycled {n} today)",
    "♻️ 丟進回收桶了！{n} 件垃圾 +{g} 🌰": "♻️ Recycled {n} pieces of trash +{g} 🌰",
    "♻️ 丟進回收桶了！今天換松果的次數已經滿了，謝謝你讓營地更乾淨": "♻️ Recycled! You've hit today's pinecone limit — thanks for keeping camp clean",
