    "湖裡": "In the lake",
    "湖邊": "Lakeshore",
    "營地路邊": "Camp paths",
    "營火區": "Campfire",
    "湖裡釣魚、湖邊、帳篷營地的路邊、中央營火區，偶爾會出現垃圾，走過去按 E 撿起來。撿到的垃圾拿去營火旁的「♻️ 回收桶」丟，每件換 1 顆松果（每天最多 {cap} 顆）。全部收集完送「淨灘小隊領巾」♻️": "Trash sometimes turns up while fishing, on the lakeshore, along camp paths and around the campfire — walk over and press E. Bring it to the ♻️ recycling bin by the campfire for 1 pinecone each (up to {cap} a day). Complete the guide for the Cleanup Crew bandana ♻️",
    "🗑️ 垃圾袋": "🗑️ Trash bag",
