    "🔥 名字前面的小營火徽章，大家都看得到": "🔥 A little campfire badge before your name that everyone can see",
    "⛺ 月票限定帳篷花色「營火之夜」（買過就一直留著）": "⛺ Pass-exclusive tent pattern \"Campfire Night\" (yours to keep)",
