    "付款由綠界處理（信用卡、ATM、超商代碼），付款完成後自動開通，不用等人工。月票只會加快松果累積，遊戲裡所有東西不買也都拿得到。": "Payment is handled by ECPay (card, ATM, convenience store) and activates automatically. The pass only speeds up pinecones — everything in the game can be earned without it.",
