    "🎁 送給 {name} 了！": "🎁 {name} にあげたよ！",
    "🎁 送朋友": "🎁 プレゼント",
    "🎁 把 {icon} {item} 送給誰？": "🎁 {icon} {item} をだれにあげる？",
    "還沒有好友。點下面「👫 好友」加朋友，就能互相送禮了": "まだ友だちがいないよ。下の「👫 友だち」で友だちになると、プレゼントしあえるよ",
    "選一位好友，送 1 個（價值 {v} 🌰）": "友だちを1人えらんで1個プレゼント（価値 {v} 🌰）",
