    "📌 獎勵都是系統照上面的規則自動發的：沒有符合條件就不會拿到，作者不另外補發。邀請前請先跟朋友確認好": "📌 報酬は上のルールどおりシステムが自動で配ります。条件を満たさないともらえず、作者からの補償もありません。招待する前に友だちと確認してね",
    "❌ 不算的情況：自己點自己的連結、只傳圖片沒掃 QR、朋友以前就來過（不算「新朋友」，但每日造型、營火之約還是算）": "❌ カウントされない：自分のリンクを自分で開く、画像だけ送ってQRを読まない、前に来たことがある友だち（「新しい友だち」にはならないが、日替わりコーデと焚き火の約束はOK）",
    "⏳ 朋友中途跳出去沒關係，30 分鐘內回來還是算；時間到之前關掉、30 分鐘內沒回來就不算": "⏳ 途中で抜けても30分以内に戻ればOK。時間前に閉じて30分以内に戻らないとカウントされません",
    "🏢 <b>同一個網路</b>（同事、家人用同一個 Wi‑Fi）：朋友要待 {m} 分鐘，而且要玩一下（釣魚、採集、撿垃圾、做任務都可以），同一個網路每天最多算 {n} 位": "🏢 <b>同じネットワーク</b>（同僚・家族で同じWi‑Fi）：友だちは{m}分いて、少し遊ぶ必要あり（釣り・採集・ごみ拾い・任務など）。同じネットワークは一日{n}人まで",
    "🔥 <b>營火之約</b>：早上、晚上 9:30～10:00 營火時間，朋友點你的連結進來待滿 {m} 分鐘，兩個人都拿限定造型（依序：營火圍巾 → 烤棉花糖帽 → 流星燈背架），同一對朋友每天算一次": "🔥 <b>焚き火の約束</b>：朝・夜9:30〜10:00の焚き火タイムに友だちがリンクから入り{m}分いると、二人とも限定コーデ（順に：焚き火マフラー→焼きマシュマロ帽→流れ星ランタン）。同じ二人は一日一回",
    "👒 <b>每日造型</b>：任何朋友（新朋友、老朋友都算）點你的連結進來玩 {m} 分鐘；或自己完成「今日挑戰」3 題": "👒 <b>日替わりコーデ</b>：友だち（新旧問わず）があなたのリンクから{m}分遊ぶ、または「今日のチャレンジ」3つを自分でクリア",
