    "🏛️ 營地標本櫃 {n}／{total}": "🏛️ キャンプの標本だな {n}／{total}",
    "大家一起把採集到的東西捐進標本櫃，每一格都會寫上「第一個捐的人」的名字。捐出一個送松果（★ 越多送越多）。": "みんなで採集したものを標本だなに寄付しよう。各マスに「最初に寄付した人」の名前が残るよ。寄付すると松ぼっくり（★が多いほどたくさん）。",
    "🏛️ 捐進標本櫃了！你的名字會留在這一格 +{n} 🌰": "🏛️ 寄付したよ！このマスにあなたの名前が残る +{n} 🌰",
