    "朋友要「點你的連結」或「掃邀請圖上的 QR Code」進來才算數": "友だちが「あなたのリンク」か「招待画像のQRコード」から来たときだけカウントされるよ",
    "📋 複製連結": "📋 リンクをコピー",
    "📤 分享連結": "📤 リンクをシェア",
    "🖼️ 邀請圖（有 QR Code）": "🖼️ 招待画像（QRつき）",
    "👒 今天的每日造型・朋友點你的連結進來玩 1 分鐘，或完成下面的「今日挑戰」": "👒 今日の日替わりコーデ・友だちがリンクから1分遊ぶか、下の「今日のチャレンジ」をクリア",
    "🌟 這週限定造型・朋友第一次透過你的連結來玩，待滿 {m} 分鐘": "🌟 週替わり限定コーデ・友だちがはじめてリンクから来て{m}分いたら",
    "🔥 營火之約限定・晚上 9:30～10:00 朋友透過你的連結進來，兩個人都拿到": "🔥 たき火の約束限定・夜9:30〜10:00に友だちがリンクから来るとふたりともゲット",
    "{kind}・第一次分享": "{kind}・はじめてのシェア",
    "{kind}・{n} 位朋友透過你的連結來玩": "{kind}・{n}人の友だちがリンクから遊びに来る",
    "已經有 {n} 位朋友透過你的連結來玩。每位朋友第一次來、待滿 {m} 分鐘，你就多 {g} 顆松果。只傳圖片的話，請朋友掃圖上的 QR Code 才算喔": "これまでに{n}人の友だちがリンクから来たよ。はじめて来て{m}分いると松ぼっくり{g}個。画像だけ送るときは、QRコードを読んでもらってね",
    "複製不了，請長按上面的連結自己複製": "コピーできなかったよ、上のリンクを長押ししてコピーしてね",
    "📋 已複製邀請連結，貼到 LINE、Threads、IG 給朋友吧": "📋 招待リンクをコピーしたよ、LINE・Threads・IGで友だちに貼ってね",
    "有些 App（像 IG、LINE）分享圖片時會把連結拿掉，朋友掃圖上的 QR Code 一樣算是透過你的連結進來 📱": "IGやLINEなど、画像をシェアするとリンクが消えるアプリもあるよ。画像のQRコードを読んでもらえばOK 📱",
    "朋友點連結進來玩 1 分鐘，就送你今天的每日造型：{name}": "友だちがリンクから来て1分遊ぶと、今日のコーデ「{name}」がもらえる",
    "📱 掃描 QR Code": "📱 QRコードを読みこむ",
    "就會出現在我旁邊，免安裝打開就能玩": "わたしのとなりに出てくるよ、インストール不要",
    "就會出現在我旁邊": "わたしのとなりに出てくるよ",
    "免安裝，打開就能玩": "インストール不要、開けばすぐ遊べる",
    "🖼️ QR 邀請圖": "🖼️ QR招待画像",
    "📋 複製文案": "📋 文章をコピー",
    "📋 文案和連結複製好了，貼到 LINE、Threads、IG 都可以": "📋 文章とリンクをコピーしたよ、LINE・Threads・IGに貼れるよ",
    "✅ 圖片分享出去了！文案和連結也幫你複製好了，如果朋友那邊沒看到連結，在聊天框長按「貼上」就好": "✅ 画像をシェアしたよ！文章とリンクもコピー済み。リンクが届いてなかったら、チャット欄で長押しして「貼り付け」してね",
    "✅ 分享出去了！圖片可以按「存圖」另外傳": "✅ シェアしたよ！画像は「保存」して別に送れるよ",
    "按「📤 分享」會順便複製下面的文案和連結：如果 App 只送出圖片，在聊天框貼上就好；朋友掃圖上的 QR Code 也算 📱": "「📤 シェア」すると下の文章とリンクもコピーされるよ。アプリが画像だけ送ったら、チャット欄に貼り付けてね。QRコードを読んでもOK 📱",
    "🌱 還可以再開墾（最多 {max} 格）": "🌱 まだ開墾できるよ（最大{max}マス）",
    "➕ 開墾第 {n} 格 🌰 {p}": "➕ {n}マス目を開墾 🌰 {p}",
    "🌱 開墾好了！菜園現在有 {n} 格": "🌱 開墾できた！菜園は{n}マスになったよ",
    "現在不能開墾": "今は開墾できないよ",
    "魚拓": "魚拓",
    "🎣 捐魚拓": "🎣 魚拓を寄付",
    "大家一起把採集到的東西、釣過的魚拓捐進標本櫃，每一格都會寫上「第一個捐的人」。每個人每天只能捐一件，慢慢一起填滿吧！捐出一件送松果（★ 越多送越多）。": "みんなで採集したものや魚拓を標本だなに寄付しよう。各マスに「最初に寄付した人」の名前が残るよ。ひとり1日1つだけ、ゆっくり一緒にうめていこう！寄付すると松ぼっくり（★が多いほどたくさん）。",
    "🎁 今天還可以捐 {n} 件": "🎁 今日はあと{n}つ寄付できるよ",
    "✅ 今天已經捐過了，明天再來捐下一件吧": "✅ 今日はもう寄付したよ、また明日ね",
