    "♻️ 垃圾圖鑑新收錄：{icon} {name}！+{n} 🌰（{c}／{t}）": "♻️ ゴミ図鑑に新登録：{icon} {name}！+{n} 🌰（{c}／{t}）",
    "♻️ 撿起了{icon} {name}，記得拿去營火旁的回收桶": "♻️ {icon} {name}を拾ったよ、たき火のそばのリサイクル箱へ",
    "🏆 垃圾圖鑑全部收集完成！送你「淨灘小隊領巾」": "🏆 ゴミ図鑑コンプリート！「おそうじ隊のバンダナ」をプレゼント",
    "♻️ {name} 撿起了{icon} {item}": "♻️ {name}さんが{icon} {item}を拾ったよ",
    "連上伺服器才能回收": "サーバーにつながるとリサイクルできるよ",
    "垃圾袋是空的。湖邊、帳篷營地路邊、營火附近偶爾會有垃圾，撿起來再拿過來丟 ♻️（今天大家一起回收了 {n} 件）": "ゴミ袋は空だよ。湖のほとり、キャンプ場の道ばた、たき火の近くにときどきゴミがあるので、拾ってきてね ♻️（今日はみんなで{n}個リサイクル）",
