    "♻️ 丟進回收桶了！今天換松果的次數已經滿了，謝謝你讓營地更乾淨": "♻️ リサイクルしたよ！今日の松ぼっくりはもう上限、キャンプをきれいにしてくれてありがとう",
    "（今天大家一起回收了 {d} 件）": "（今日はみんなで{d}個リサイクル）",
