    "直立的大圓殼加上閉眼微笑的蝸牛，觸角上是會發光的小燈": "커다란 둥근 껍데기와 웃는 달팽이, 더듬이 끝엔 빛나는 작은 램프",
    "蝸牛殼屋　🌰 120": "달팽이 껍데기 집 🌰 120",
    "🏕️ 新帳篷上架了！": "🏕️ 새 텐트 출시!",
    "連續滿 3 天送一款聖誕造型（斷一天要重算）": "3일 연속 접속하면 크리스마스 코디 하나 (하루 빠지면 다시 시작)",
    "🎄 連續上線 {n}／{need} 天": "🎄 연속 접속 {n}/{need}일",
    "到「👒 造型」穿上": "\"👒 코디\"에서 입어 보세요",
    "🎄 連續上線 3 天！送你聖誕造型：{name}": "🎄 3일 연속 접속! 크리스마스 코디 선물: {name}",
    "🎄 連續上線 3 天！拿到聖誕造型：{name}": "🎄 3일 연속 접속! 크리스마스 코디 획득: {name}",
    "和風小屋": "일본풍 오두막",
    "花園溫室": "정원 온실",
    "南瓜屋": "호박 집",
