    "🎄 12/1 才開賣喔": "🎄 12/1부터 판매해요",
    "💛 謝謝你的贊助！聖誕禮盒送到了：{list}（家具在背包裡，到帳篷就能擺）": "💛 후원 고마워요! 크리스마스 상자가 도착했어요: {list} (가구는 가방에 있어요, 텐트에서 놓을 수 있어요)",
    "🎒 家具會放進背包，到帳篷就能擺": "🎒 가구는 가방에 들어가요. 텐트에서 놓을 수 있어요",
    "💇 選一款假髮（NT$100 選假髮、NT$150 以上會送）": "💇 가발 선택 (NT$100에서 가발을 고르면, NT$150 이상은 포함)",
    "限定假髮": "한정 가발",
    "NT$100 想要哪一個？": "NT$100이면 어느 쪽?",
    "🎁 小東西選一件（NT$200 三件都送）": "🎁 소품 1개 선택 (NT$200은 3개 모두)",
    "小東西 3 件全部＋假髮＋{big}": "소품 3개 전부 + 가발 + {big}",
    "小東西 1 件＋假髮＋{big}": "소품 1개 + 가발 + {big}",
    "小東西 1 件＋假髮或{big}（2 選 1）": "소품 1개 + 가발 또는 {big} (1개 선택)",
    "小東西 1 件（3 選 1）": "소품 1개 (3개 중 1개)",
    "這座營地是一個人慢慢做出來的，伺服器需要一點費用。{m} 月的聖誕禮盒，依金額送你不同的東西：": "이 캠프장은 혼자서 천천히 만들고 있고, 서버 비용이 조금 들어요. {m}월 크리스마스 상자는 금액에 따라 받는 것이 달라요:",
    "🎄 聖誕期間（12/1～1/6）可以買小精靈配件：聖誕帽、紅色雪人圍巾、綠色雪人圍巾，每個 60 🌰；買了每隻小精靈都能戴，過了聖誕也能繼續戴": "🎄 크리스마스 기간(12/1~1/6)에는 정령 액세서리를 살 수 있어요: 산타 모자, 빨간 눈사람 목도리, 초록 눈사람 목도리, 각 60 🌰. 모든 정령이 착용할 수 있고 크리스마스가 지나도 계속 착용 가능",
    "聖誕襪掛架": "크리스마스 양말 걸이",
    "禮物盒堆": "선물 상자 더미",
    "薑餅屋": "진저브레드 하우스",
    "室內聖誕樹": "실내 크리스마스 트리",
    "綠色小雪人圍巾": "초록 눈사람 목도리",
    "紅色小雪人圍巾": "빨간 눈사람 목도리",
