    "聖誕帽": "산타 모자",
    "船屋": "하우스보트",
    "北極熊雪屋": "북극곰 이글루",
    "🎄 心願聖誕樹": "🎄 소원 크리스마스 트리",
    "小精靈綠色雪人圍巾": "정령 초록 눈사람 목도리",
    "小精靈紅色雪人圍巾": "정령 빨간 눈사람 목도리",
    "小精靈聖誕帽": "정령 산타 모자",
    "松果不夠": "솔방울이 부족해요",
    "這個配件現在沒有賣了": "이 액세서리는 지금 판매하지 않아요",
    "花 {n} 🌰 買{icon} {name}？買了每隻小精靈都能戴": "{n} 🌰로 {icon} {name} 구매할까요? 모든 정령이 착용 가능",
    "拿下來": "벗기",
    "戴上": "착용",
