    "🧺 採到{icon} {name}，採集達人多拿一個！（採集籃裡有 {n} 個）": "🧺 {icon} {name} 획득, 채집 달인 보너스로 하나 더! (바구니에 {n}개)",
    "📌 獎勵都是系統照上面的規則自動發的：沒有符合條件就不會拿到，作者不另外補發。邀請前請先跟朋友確認好": "📌 보상은 위 규칙에 따라 시스템이 자동으로 줘요. 조건을 못 채우면 받을 수 없고, 제작자가 따로 보내 주지 않아요. 초대 전에 친구와 꼭 확인하세요",
    "❌ 不算的情況：自己點自己的連結、只傳圖片沒掃 QR、朋友以前就來過（不算「新朋友」，但每日造型、營火之約還是算）": "❌ 인정 안 되는 경우: 내 링크를 내가 누르기, 이미지만 보내고 QR을 안 찍기, 전에 와 본 친구 (「새 친구」는 아니지만 데일리 코디·모닥불 약속은 인정)",
    "⏳ 朋友中途跳出去沒關係，30 分鐘內回來還是算；時間到之前關掉、30 分鐘內沒回來就不算": "⏳ 친구가 잠깐 나가도 30분 안에 돌아오면 인정돼요. 시간 전에 닫고 30분 안에 안 돌아오면 인정 안 돼요",
    "🏢 <b>同一個網路</b>（同事、家人用同一個 Wi‑Fi）：朋友要待 {m} 分鐘，而且要玩一下（釣魚、採集、撿垃圾、做任務都可以），同一個網路每天最多算 {n} 位": "🏢 <b>같은 네트워크</b> (동료·가족이 같은 Wi‑Fi): 친구가 {m}분 머물며 조금 놀아야 해요 (낚시, 채집, 쓰레기 줍기, 임무 등). 같은 네트워크는 하루 최대 {n}명",
    "🔥 <b>營火之約</b>：早上、晚上 9:30～10:00 營火時間，朋友點你的連結進來待滿 {m} 分鐘，兩個人都拿限定造型（依序：營火圍巾 → 烤棉花糖帽 → 流星燈背架），同一對朋友每天算一次": "🔥 <b>모닥불 약속</b>: 아침·저녁 9:30~10:00 모닥불 시간에 친구가 내 링크로 들어와 {m}분 머물면 둘 다 한정 코디 (순서: 모닥불 목도리 → 구운 마시멜로 모자 → 별똥별 등불 배낭). 같은 둘은 하루 한 번",
    "👒 <b>每日造型</b>：任何朋友（新朋友、老朋友都算）點你的連結進來玩 {m} 分鐘；或自己完成「今日挑戰」3 題": "👒 <b>데일리 코디</b>: 친구(새 친구·기존 친구 모두)가 내 링크로 {m}분 놀거나, 「오늘의 도전」 3개를 직접 완료",
    "👫 <b>新朋友</b>：第一次來營地、點你的連結（或掃 QR 邀請圖）進來，待滿 {m} 分鐘 → 你拿 {g} 顆松果＋這週限定造型；累積 1、3、5 位送禮物家具": "👫 <b>새 친구</b>: 처음 방문해서 내 링크(또는 QR)로 들어와 {m}분 머물면 → 솔방울 {g}개 + 이번 주 한정 코디. 1·3·5명이면 선물 가구",
