    "🌙 每晚 7 點～11 點，每半小時一場小活動（9:30 營火時間有魚王）": "🌙 매일 밤 7시~11시, 30분마다 미니 이벤트 (9:30 모닥불 타임엔 물고기왕)",
    "想動就去釣魚、疊石頭；想靜就在火邊坐著。每晚 7 點～11 點，每半小時一場小活動 🎣": "움직이고 싶으면 낚시나 돌 쌓기, 조용히 있고 싶으면 모닥불 옆에. 매일 밤 7시~11시 30분마다 미니 이벤트 🎣",
    "🍄 迷霧森林：地上有發光圈圈的蘑菇、果實、野花，走過去按 E 採摘；空中飛的蟲蟲要用捕蟲網（{p} 🌰）按 E 捕。🐚 湖畔碼頭的岸邊可以撿石頭和貝殼。✨ 晚上 8～10 點營火附近偶爾會有寶藏。第一次找到新的種類送松果，全部收集完再送 {b} 顆 🌰": "🍄 안개 숲: 빛나는 고리가 있는 버섯·열매·꽃에 가서 E로 채집, 날아다니는 곤충은 잠자리채({p} 🌰)로 E. 🐚 호숫가에선 돌과 조개. ✨ 밤 8~10시엔 모닥불 근처에 가끔 보물. 새 종류를 찾으면 솔방울, 다 모으면 {b}개 더 🌰",
    "🦋 捕蟲網：已經有了": "🦋 잠자리채: 있음",
    "🦋 捕蟲網：還沒有": "🦋 잠자리채: 아직 없음",
