    "空中飛的蟲蟲要用捕蟲網才捕得到。買一支之後一直都能用：白天有瓢蟲、金龜子、螳螂⋯，晚上有螢火蟲、獨角仙、月光蛾⋯": "날아다니는 곤충은 잠자리채가 있어야 잡을 수 있어요. 한 번 사면 계속 사용: 낮엔 무당벌레·풍뎅이·사마귀, 밤엔 반딧불이·장수풍뎅이·달빛 나방⋯",
