    "♻️ 撿起了{icon} {name}，記得拿去營火旁的回收桶": "♻️ {icon} {name}를 주웠어요, 모닥불 옆 분리수거함에 버려요",
    "🏆 垃圾圖鑑全部收集完成！送你「淨灘小隊領巾」": "🏆 쓰레기 도감 완성! '청소 대원 반다나'를 선물해요",
    "♻️ {name} 撿起了{icon} {item}": "♻️ {name} 님이 {icon} {item}를 주웠어요",
    "連上伺服器才能回收": "서버에 연결해야 분리수거할 수 있어요",
    "垃圾袋是空的。湖邊、帳篷營地路邊、營火附近偶爾會有垃圾，撿起來再拿過來丟 ♻️（今天大家一起回收了 {n} 件）": "쓰레기봉투가 비었어요. 호숫가, 캠프장 길가, 모닥불 근처에 가끔 쓰레기가 있으니 주워 와요 ♻️ (오늘 모두 {n}개 분리수거)",
    "♻️ 丟進回收桶了！{n} 件垃圾 +{g} 🌰": "♻️ 분리수거 완료! 쓰레기 {n}개 +{g} 🌰",
    "♻️ 丟進回收桶了！今天換松果的次數已經滿了，謝謝你讓營地更乾淨": "♻️ 분리수거 완료! 오늘 솔방울은 이미 최대예요, 캠프를 깨끗하게 해줘서 고마워요",
    "（今天大家一起回收了 {d} 件）": " (오늘 모두 {d}개 분리수거)",
    "♻️ 垃圾": "♻️ 쓰레기",
    "♻️ 垃圾圖鑑 {n}／{total}": "♻️ 쓰레기 도감 {n}/{total}",
    "撿過 {n} 次": "{n}번 주움",
    "湖裡": "호수 속",
    "湖邊": "호숫가",
    "營地路邊": "캠프장 길가",
    "營火區": "모닥불 주변",
    "湖裡釣魚、湖邊、帳篷營地的路邊、中央營火區，偶爾會出現垃圾，走過去按 E 撿起來。撿到的垃圾拿去營火旁的「♻️ 回收桶」丟，每件換 1 顆松果（每天最多 {cap} 顆）。全部收集完送「淨灘小隊領巾」♻️": "낚시 중, 호숫가, 캠프장 길가, 모닥불 주변에 가끔 쓰레기가 나와요. 다가가서 E로 주워요. 모닥불 옆 ♻️ 분리수거함에 버리면 하나당 솔방울 1개 (하루 최대 {cap}개). 다 모으면 '청소 대원 반다나' ♻️",
