    "🌰 之後 {d} 天，每天第一次進來多領 {n} 顆（當天沒來就領不到）": "🌰 이후 {d}일 동안 매일 처음 들어오면 +{n}개 (안 온 날은 못 받아요)",
    "🔥 名字前面的小營火徽章，大家都看得到": "🔥 이름 앞에 작은 모닥불 배지, 모두에게 보여요",
    "⛺ 月票限定帳篷花色「營火之夜」（買過就一直留著）": "⛺ 패스 한정 텐트 무늬 '모닥불의 밤' (계속 보관)",
    "購買前要先建立帳號（👤 存檔），換手機登入月票才不會不見": "구매 전에 계정을 만들어요 (👤 저장), 폰을 바꿔도 패스가 사라지지 않아요",
