    "付款由綠界處理（信用卡、ATM、超商代碼），付款完成後自動開通，不用等人工。月票只會加快松果累積，遊戲裡所有東西不買也都拿得到。": "결제는 ECPay가 처리하고 (카드·ATM·편의점), 결제 후 자동 개통돼요. 패스는 솔방울만 빨리 모일 뿐, 게임의 모든 것은 구매 없이도 얻을 수 있어요.",
    "購買前要先建立帳號（👤 存檔）": "구매 전에 계정을 만들어요 (👤 저장)",
    "現在不能購買，等一下再試": "지금은 구매할 수 없어요, 잠시 후 다시",
    "🎫 已經打開綠界付款頁，付款完成後回到遊戲就會自動開通": "🎫 결제 페이지를 열었어요, 결제 후 자동 개통돼요",
