    "小舖新帳篷「雙層小木屋」，二樓也能擺家具；帳篷最大可以擴建到 20×20": "상점에 새로운 '2층 통나무집', 2층에도 가구를 놓을 수 있어요. 텐트는 최대 20×20까지 확장",
